/**
 * Pre-deployment sanity checks. Run before deploying: `npm run pre-deploy`.
 * Exits non-zero when a required file or setting is missing.
 */
const fs = require("fs");
const path = require("path");

const root = path.resolve(__dirname, "..");
const exists = (p) => fs.existsSync(path.join(root, p));
let failed = false;
const check = (ok, ok_msg, bad_msg) => {
  if (ok) console.log(`✅ ${ok_msg}`);
  else {
    failed = true;
    console.error(`❌ ${bad_msg}`);
  }
};

console.log("🔍 Running pre-deployment checks...\n");

// SEO and PWA routes are generated by the app router (sitemap.ts, robots.ts, manifest.ts).
for (const f of ["src/app/sitemap.ts", "src/app/robots.ts", "src/app/manifest.ts", "src/app/opengraph-image.tsx"]) {
  check(exists(f), `${f} exists`, `${f} is missing`);
}
// Static files that would shadow the generated routes.
for (const f of ["public/sitemap.xml", "public/robots.txt", "public/manifest.json"]) {
  check(!exists(f), `${f} not present (generated by the app)`, `${f} exists and would conflict with the generated route`);
}

// Every page that has a sitemap entry must exist, and vice versa.
const seo = fs.readFileSync(path.join(root, "src/lib/seo.ts"), "utf8");
const paths = [...seo.matchAll(/^\s+"(\/[^"]*)": \{/gm)].map((m) => m[1]);
for (const p of paths) {
  const file = p === "/" ? "src/app/page.tsx" : `src/app${p}/page.tsx`;
  check(exists(file), `${p} has a page (${file})`, `${p} is listed in seo.ts but ${file} is missing`);
}

// Large files in public/
const MAX_MB = 1;
const walk = (dir) =>
  fs.readdirSync(dir).flatMap((f) => {
    const full = path.join(dir, f);
    return fs.statSync(full).isDirectory() ? walk(full) : [full];
  });
for (const f of walk(path.join(root, "public"))) {
  const mb = fs.statSync(f).size / (1024 * 1024);
  if (mb > MAX_MB) console.warn(`⚠️  Large file in public/: ${path.relative(root, f)} (${mb.toFixed(2)} MB)`);
}

const gaSet = !!process.env.NEXT_PUBLIC_GA_ID;
console.log(gaSet ? "✅ NEXT_PUBLIC_GA_ID is set" : "ℹ️  NEXT_PUBLIC_GA_ID not set: analytics use the built-in fallback property");

console.log("\n💡 Also run: npm run typecheck && npm test && npm run lint, then Lighthouse on a mobile profile.");
if (failed) {
  console.error("\n❌ Pre-deployment checks failed.");
  process.exit(1);
}
console.log("\n✅ Pre-deployment checks passed.");
